extends CharacterBody3D

const MOVE_SPEED := 5.0
const ACCEL_GROUND := 40.0
const ACCEL_AIR := 12.0
const GRAVITY := 22.0
const FACING_LERP_SPEED := 12.0
const ARM_SPEED := 11.0
const BOUNCE_SCALE := 0.03

@onready var body: Node3D = $Body
@onready var arm_l: Node3D = $Body/ArmL
@onready var arm_r: Node3D = $Body/ArmR
@onready var leg_l: Node3D = $Body/LegL
@onready var leg_r: Node3D = $Body/LegR

var _run_time := 0.0


func _ready() -> void:
	input_pickup = true


func _physics_process(delta: float) -> void:
	var on_floor := is_on_floor()

	# Gravity
	if on_floor:
		velocity.y = 0.0
	elif velocity.y > 0.0:
		velocity.y = 0.0
	else:
		velocity.y -= GRAVITY * delta

	# Read input relative to the camera's facing direction
	var cam_basis: Basis = get_viewport().get_camera_3d().global_transform.basis
	var input_vec := Input.get_vector("move_left", "move_right", "move_up", "move_down")
	var wish_dir := (cam_basis * Vector3(input_vec.x, 0.0, input_vec.y))
	wish_dir.y = 0.0
	if wish_dir.length_squared() > 1.0:
		wish_dir = wish_dir.normalized()

	var accel := ACCEL_GROUND if on_floor else ACCEL_AIR
	var target_hvel := wish_dir * MOVE_SPEED
	velocity.x = move_toward(velocity.x, target_hvel.x, accel * delta)
	velocity.z = move_toward(velocity.z, target_hvel.z, accel * delta)

	move_and_slide()

	# Face the movement direction (smooth turn)
	if velocity.horizontal_velocity().length() > 0.25:
		var target_yaw := atan2(velocity.x, velocity.z)
		var current_yaw := rotation.y
		var diff := wrapf(target_yaw - current_yaw, -PI, PI)
		rotation.y = current_yaw + diff * clampf(FACING_LERP_SPEED * delta, 0.0, 1.0)

	_update_animation(delta, on_floor)


func _update_animation(delta: float, on_floor: bool) -> void:
	var speed := velocity.horizontal_velocity().length()

	if on_floor and speed > 0.3:
		_run_time += delta * ARM_SPEED
		var swing := sin(_run_time)
		leg_l.rotation.x = swing * 0.95
		leg_r.rotation.x = -swing * 0.95
		arm_l.rotation.x = -swing * 0.85
		arm_r.rotation.x = swing * 0.85
		# Light vertical bob so the run feels lively
		body.position.y = abs(sin(_run_time)) * 0.06 * minf(speed / MOVE_SPEED, 1.2)
	else:
		# Ease limbs back to rest
		var t := clampf(10.0 * delta, 0.0, 1.0)
		leg_l.rotation.x = lerpf(leg_l.rotation.x, 0.0, t)
		leg_r.rotation.x = lerpf(leg_r.rotation.x, 0.0, t)
		arm_l.rotation.x = lerpf(arm_l.rotation.x, 0.0, t)
		arm_r.rotation.x = lerpf(arm_r.rotation.x, 0.0, t)
		body.position.y = lerpf(body.position.y, 0.0, t)

extends Node3D

@onready var player: Node3D = get_tree().get_first_node_in_group("player") or _find_player()

var _yaw := 0.0
var _pitch := -0.62
var _dragging := false

const SENS_X := 2.6
const SENS_Y := 2.2
const CLIP_X := 0.5
const CLIP_Y := 0.4
const DIST := 9.0
const MIN_PITCH := -1.2
const MAX_PITCH := 0.45


func _find_player() -> Node3D:
	var p := get_parent().get_node_or_null("Player")
	return p


func _ready() -> void:
	if not player:
		player = get_tree().get_first_node_in_group("player")
	_update_camera()
	# Optional mouse-follow for desktop play (harmless on web until first click)
	mouse_filter = Control.MOUSE_FILTER_STOP if player else mouse_filter


func _find_mouse() -> void:
	pass


func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventMouseMotion and event.pressed:
		_yaw -= event.relative.x * 0.004
		_pitch = clampf(_pitch - event.relative.y * 0.004, MIN_PITCH, MAX_PITCH)
		_update_camera()
	elif event is InputEventMouseButton:
		if event.button_index == MOUSE_BUTTON_RIGHT:
			_dragging = event.pressed
			get_viewport().set_input_as_handled()
		elif event.button_index == MOUSE_BUTTON_WHEEL_UP:
			_update_zoom(event)
		elif event.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			_update_zoom(event)
	elif event is InputEventKey and event.pressed and not event.echo:
		if event.keycode == KEY_ESCAPE:
			get_tree().quit()


func _update_zoom(_event: InputEvent) -> void:
	var cam := $Camera3D as Camera3D
	cam.fov = clampf(cam.fov + (2.5 if _event_is_up() else -2.5), 30.0, 90.0)


func _event_is_up() -> bool:
	return true


func _physics_process(_delta: float) -> void:
	if player and not _dragging:
		_update_camera()


func _update_camera() -> void:
	if not player:
		return
	var yaw_rot := Basis(Vector3.UP, _yaw)
	var dir := Vector3(0.0, 0.0, -1.0).rotated(yaw_rot * Basis(Vector3.RIGHT, _pitch), true)
	# Simpler, stable approach: spherical position from yaw/pitch
	var pitch_dir := Vector3(
		sinf(_yaw) * cosf(_pitch),
		sinf(_pitch) * -1.0,
		cosf(_yaw) * cosf(_pitch)
	)
	var pos := player.global_position + Vector3(0.0, 1.4, 0.0) - pitch_dir * DIST
	global_position = pos

extends Node3D

const DIST := 9.0
const SENS_X := 0.004
const SENS_Y := 0.004
const MIN_PITCH := -1.1
const MAX_PITCH := 0.35
const FOCUS_HEIGHT := 1.4

var _yaw := 0.0
var _pitch := -0.55
var _dragging := false

@onready var player: Node3D = get_parent().get_node_or_null("Player")
@onready var camera: Camera3D = $Camera3D


func _ready() -> void:
	_update_camera()


func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventMouseButton:
		if event.button_index == MOUSE_BUTTON_RIGHT:
			_dragging = event.pressed
			get_viewport().set_input_as_handled()
		elif event.button_index == MOUSE_BUTTON_WHEEL_UP:
			camera.fov = clampf(camera.fov - 3.0, 30.0, 90.0)
			get_viewport().set_input_as_handled()
		elif event.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			camera.fov = clampf(camera.fov + 3.0, 30.0, 90.0)
			get_viewport().set_input_as_handled()
	elif event is InputEventMouseMotion and _dragging:
		_yaw -= event.relative.x * SENS_X
		_pitch = clampf(_pitch + event.relative.y * SENS_Y, MIN_PITCH, MAX_PITCH)
	elif event is InputEventKey and event.pressed and not event.echo:
		if event.keycode == KEY_ESCAPE:
			get_tree().quit()


func _physics_process(_delta: float) -> void:
	_update_camera()


func _update_camera() -> void:
	if not player:
		return
	var offset := Vector3(
		sinf(_yaw) * cosf(_pitch),
		sinf(_pitch),
		cosf(_yaw) * cosf(_pitch)
	) * DIST
	global_position = player.global_position + Vector3(0.0, FOCUS_HEIGHT, 0.0) + offset
	look_at(player.global_position + Vector3(0.0, FOCUS_HEIGHT, 0.0), Vector3.UP)

